from vc_kit import *
from vc_part1 import B, T

CH5 = dict(title='The Harlem of the South', years='1896–1970', mood='grief', beats=[
  B("Now go back to Colored Town, the district the city's Black founders were pushed into. Over the next fifty years, something remarkable grows there.",
    S('day', houses(n=6), palms(y=.86, n=2, x0=.1, gap=.7), push=.05), date="1940s\nOVERTOWN, MIAMI"),
  B("Black owned shops, churches, lodges, a newspaper, The Miami Times, founded in 1923 and still printing today. Theatres and clubs along a strip people call Little Broadway.",
    S('night', houses(night=True, n=6), neon('LYRIC', x=.3, y=.32, col='255,180,60', size=90), neon('LITTLE BROADWAY', x=.68, y=.22, col='255,60,170', size=70)),
    ('Times', D(['THE MIAMI TIMES', 'founded 1923', 'still published today'], 'Overtown', hl=[0]))),
  B("The biggest names in music play to packed crowds there, late into the night. Nat King Cole. Billie Holiday.",
    S('night', room(night=True, wall='#3a2430', window=None), crowd(n=40, y=1.0), A(('citizen80s', .5, 'wave', {'spec': {'coat': '#e8e0d0'}})), push=.08),
    ('Holiday', S('night', houses(night=True), neon('LIVE TONIGHT', y=.3, col='255,90,60'), crowd(n=50, y=1.0)))),
  B("By around 1950, about fifty thousand people live in Overtown. They call it the Harlem of the South.",
    C('50,000', 'PEOPLE IN OVERTOWN', 'around 1950', size=200), ('Harlem', S('day', houses(n=7), crowd(n=60, y=1.0), push=.06))),
  T([('RES1', "Where were you last night?"), ('RES2', "The Lyric. You should have heard her."), ('RES1', "On a Tuesday?")],
    S('night', houses(night=True, n=5), A(('citizen80s', .3, 'idle', {'spec': {'coat': '#4a3a5a'}}), ('woman', .7, 'hips', {'spec': {'skin': '#8a5a3a'}})))),
  B("Then, in the nineteen sixties, the government decides to build an interstate highway into downtown Miami. Interstate 95, and a link road to the beaches, Interstate 395.",
    MAP, ('Interstate', S('day', houses(n=6), A(('clerk', .5, 'point', {'prop': 'paper'}))))),
  B("The route goes straight through the heart of Overtown. Homes, businesses, dozens of churches and several schools are seized and knocked down.",
    S('day', houses(n=6), A(('worker', .3, 'dig', {'prop': 'shovel'})), fx=['dust']),
    ('churches', S('day', land('mud', y=.76), fx=['dust', 'smoke'], push=.1))),
  T([('RES1', "Where are we supposed to go?"), ('OFF', "Somewhere else."), ('RES1', "Where else will have us?", 'angry')],
    S('day', houses(n=4), A(('citizen80s', .3, 'shrug', {'spec': {'coat': '#5a4a3a'}}), ('clerk', .7, 'hold', {'prop': 'paper'})))),
  B("More than twelve thousand residents are forced out. Nearly all of them are Black. Most cannot move to white neighbourhoods, so they crowd into poorer districts nearby, like Liberty City.",
    C('12,000+', 'FORCED OUT OF OVERTOWN', 'for I-95 and I-395, 1960s', size=200),
    ('Liberty', S('day', houses(n=7), crowd(n=60, y=1.0), push=.04))),
  B("By 1980, Overtown has about ten thousand people left. Where the Harlem of the South used to be, there is concrete, and the noise of traffic overhead.",
    S('day', houses(n=6), highway(y=.36), push=.06),
    ('concrete', S('dusk', highway(y=.3), land('mud', y=.8), push=.12))),
  B("Remember the expressways, too. In 1980, the space under one of them will shelter the newest arrivals in Miami. And Liberty City, where the people of Overtown were pushed, is where this city will burn.",
    S('night', highway(y=.32), houses(night=True, n=6), push=.08), sfx='tension'),
])

CH6 = dict(title='Ninety Miles', years='1959–1973', mood='tension', beats=[
  B("January 1959. In Cuba, Fidel Castro's revolution takes power. And Miami, a short flight away, is about to change for good.",
    P('castro', 'Fidel Castro, 1959'), ('Miami', MAP), date="JANUARY 1959\nHAVANA", cam={'lon': -81.0, 'lat': 24.2, 'scale': 1500}),
  B("Before the revolution, about fifty thousand Cuban Americans live in the United States. Right after it, around two hundred thousand Cubans come to South Florida.",
    C('200,000', 'CUBANS COME TO SOUTH FLORIDA', 'right after the 1959 revolution', size=200),
    ('South', S('day', sea(y=.56), ships(n=1, flag='us', s=.5, steam=True), A(('refugee', .3, 'hold', {'prop': 'paper'}), ('refugee_woman', .55, 'idle'))))),
  B("The first wave is mostly people with something to lose: officials of the old Batista government, the middle class, the rich. Many of them are sure Castro will fall soon and they will go home.",
    S('day', room(wall='#e8dcc8', window=.7), A(('politician', .3, 'cross', {'spec': {'coat': '#e8e4da'}}), ('refugee_woman', .7, 'idle', {'spec': {'coat': '#c8a0b0'}}))),
    ('home', S('dusk', sea(y=.6), A(('refugee', .5, 'think'))))),
  T([('EX1', "A few months. Then we go back."), ('EX2', "And the house?"), ('EX1', "The house will be there.")],
    S('dusk', palms(y=.86, n=4), sea(y=.66), A(('politician', .3, 'idle', {'spec': {'coat': '#e8e4da'}}), ('refugee_woman', .7, 'think')))),
  B("Downtown, a tower built in 1925 as the headquarters of the Miami News newspaper becomes the Cuban Assistance Center.",
    P('freedomtower', 'The Freedom Tower, Miami')),
  B("From 1962 to 1974 it helps the new arrivals with health care, housing, money and school. Cubans call it el refugio, the refuge. Americans call it the Ellis Island of the South. Today it's the Freedom Tower.",
    S('day', room(wall='#d8d0c0', window=.6), table(papers=10), A(('clerk', .3, 'hold', {'prop': 'paper'}), ('refugee', .7, 'idle'))),
    ('Ellis', C('ELLIS ISLAND', 'OF THE SOUTH', 'the Freedom Tower, 1962–1974', size=170))),
  B("In April 1961, some of the exiles go back the hard way. Backed by the CIA, a brigade of Cuban exiles lands at the Bay of Pigs on the seventeenth of April, to overthrow Castro.",
    S('dawn', sea(y=.6), boats(n=3, crowded=True, y=.74, s=.6), weather='fog'),
    ('seventeenth', C('17 APRIL 1961', 'THE BAY OF PIGS', 'Brigade 2506 lands', size=150))),
  B("The brigade's name is a number: 2506. It's the serial number of the first of their men, killed by accident in training in Guatemala.",
    D(['Brigade 2506', 'named for the serial number', 'of the first man killed in training'], 'Cuban exile brigade, 1961', hl=[0])),
  T([('RECRUIT', "Why 2506?"), ('VET', "That was his number. The first one we lost.")],
    S('night', camp(n=5, fire=.5), A(('cuban_soldier', .3, 'idle', {'spec': {'beard': None}}), ('cuban_soldier', .7, 'think')))),
  B("After three days of fighting, the invasion fails. From Havana's side, it's a victory over the Americans. From the exiles' side, it's a defeat Miami's Cubans will remember for decades.",
    S('day', sea(y=.6), soldiers(n=12, col='#5a6340', rows=2, march=False), fx=['smoke']),
    ('betrayal', S('dusk', sea(y=.62), palms(y=.84, n=4), A(('refugee', .5, 'think'))))),
  B("Four years later, both governments agree on something for once. From the first of December 1965, the Freedom Flights carry Cubans from Varadero Beach to Miami, twice a day, five days a week.",
    S('day', land('grass', y=.76), palms(y=.86, n=4, x0=.6, gap=.1), push=.04),
    ('twice', C('TWICE A DAY', 'FIVE DAYS A WEEK', 'Varadero to Miami, 1965–1973', size=150))),
  B("By the last flight, on the sixth of April 1973, they have brought about three hundred thousand people. The largest and longest resettlement of Cuban refugees the United States government ever ran.",
    C('300,000', 'CARRIED BY THE FREEDOM FLIGHTS', '1 December 1965 – 6 April 1973', size=200),
    ('largest', S('day', crowd(n=80, y=1.0), palms(y=.86, n=3), push=.06))),
  B("A neighbourhood near downtown fills with the new arrivals and their businesses. They call it Little Havana. Miami is becoming a Cuban city.",
    S('day', deco(words=['CAFE', 'TIENDA', 'FARMACIA', 'BODEGA', 'RADIO']), palms(y=.92, n=3, h=330, d=.85)),
    ('Havana', S('dusk', deco(night=True, words=['CAFE', 'TIENDA', 'FARMACIA', 'BODEGA', 'RADIO']), crowd(n=40, y=1.0)))),
  B("And at the same time, the other half of this story is arriving by boat and by plane, from further south. Cocaine.",
    S('night', sea(y=.62), boats(n=1, crowded=False, y=.76, s=.7, drift=1.5), push=.08), sfx='braam'),
])

CH7 = dict(title='The Cocaine Cowboys', years='1979', mood='war', beats=[
  B("By the late nineteen seventies, Colombian traffickers are flying and shipping cocaine through South Florida, and fighting each other for control of it, in the open.",
    MAP, ('Colombian', S('night', sea(y=.62), boats(n=2, crowded=False, y=.74, drift=1)))),
  B("The twentieth of May 1979. On the Florida Turnpike, two cars race each other, firing machine guns. Other drivers swerve off the road to get away. Even a police car gets shot at.",
    S('day', land('mud', y=.74), car('sedan', y=.9, s=.7, col='#2a2a2a', drive=[-.3, 1.2, 0, 4]), car('sedan', y=.95, s=.75, col='#c8b070', drive=[-.6, 1.1, .5, 4.5])),
    ('police', S('day', land('mud', y=.74), car('police', y=.94, s=.85, drive=[1.2, .4, 0, 3]), fx=['smoke'])), date="20 MAY 1979\nFLORIDA TURNPIKE"),
  B("Weeks later, a Miami Herald headline calls a restaurant shooting the Cocaine Corral. Then comes Dadeland, and the van that says Happy Time.",
    D(['"Cocaine Corral"'], 'Miami Herald headline, 1979', kind='letter', hl=[0]),
    ('Dadeland', S('day', car('van', y=.95, s=.9, text='HAPPY TIME|COMPLETE PARTY SUPPLY'), shop('CROWN LIQUORS', y=.82), push=.1))),
  B("Detectives name a suspect: Griselda Blanco, the Colombian trafficker they called the Godmother. She allegedly owed one of the dead men money. She was never tried for Dadeland.",
    S('night', room(night=True, wall='#1c1a22'), table(lamp=.5, papers=6, w=900), A(('miami_cop', .3, 'hold', {'prop': 'paper'}), ('clerk', .7, 'think'))),
    ('never', D(['DADELAND, 11 JULY 1979', 'Suspect: Griselda Blanco', 'Charged: never'], 'Case file (summary)', hl=[2]))),
  B("Dadeland is the thirty seventh and thirty eighth drug killing of the year in Miami. In 1979, the city records three hundred and forty nine murders.",
    C('349', 'MURDERS IN MIAMI', '1979', size=220),
    ('thirty', S('night', car('police', x=.4, y=.93), town(night=True, n=10), push=.06))),
  B("Now meet the hidden person of our story. Edna Buchanan, from Paterson, New Jersey. A police reporter at the Miami Herald since 1973, at a time when women were almost never given the police beat.",
    S('day', room(wall='#4a4a52', window=.6), table(papers=14, w=1000), A(('reporter', .5, 'hold', {'prop': 'paper'})), push=.06),
    ('Herald', D(['EDNA BUCHANAN', 'Police reporter, The Miami Herald', 'from 1973'], 'Press card', hl=[0]))),
  T([('EDN', "Who was he?"), ('COP3', "Nobody. A body."), ('EDN', "Everybody's somebody. What was his name?")],
    S('night', town(night=True, n=8), car('police', x=.75, y=.94), A(('reporter', .3, 'hold', {'prop': 'paper'}), ('miami_cop', .7, 'shrug')))),
  B("She works more like a detective than a journalist. Some Miami policemen say it isn't really a murder until Edna has covered it. Her opening lines become famous in the newsroom.",
    S('night', room(night=True, wall='#2a2a32'), table(lamp=.5, papers=10, w=900), A(('reporter', .4, 'think')), push=.08),
    ('opening', S('day', room(wall='#4a4a52', window=.7), table(papers=20), crowd(n=20, y=1.0)))),
  B("And at the end of 1979, she is the one who digs into a death the police want to call a traffic accident.",
    S('night', land('mud', y=.76), car('police', x=.3, y=.94), car('police', x=.75, y=.95), push=.06), sfx='tension'),
  B("The seventeenth of December 1979, early in the morning. Arthur McDuffie, thirty three, a Black insurance salesman and a former Marine, is riding his black and orange Kawasaki motorcycle in north Miami. His licence is suspended.",
    S('night', land('mud', y=.78), town(night=True, n=8), push=.04), date="17 DECEMBER 1979\nMIAMI"),
  B("Police officers chase him for about eight minutes. When it ends, a group of white officers beat him. He dies four days later, on the twenty first of December.",
    S('night', car('police', x=.4, y=.94), car('police', x=.8, y=.95), town(night=True, n=6)),
    ('dies', S('night', room(night=True, wall='#14161a'), table(lamp=.3, papers=1, w=500)))),
  B("The officers try to hide what they did. Edna Buchanan and others uncover the lies. Officers are charged with manslaughter, and with tampering with evidence.",
    D(['Charges: manslaughter,', 'tampering with evidence.', 'Four officers to stand trial.'], 'Dade County, 1980', hl=[0]),
    ('lies', S('night', room(night=True, wall='#2a2a32'), table(lamp=.5, papers=12), A(('reporter', .5, 'hold', {'prop': 'paper'}))))),
  B("The trial is moved to Tampa. It will end in May 1980. And in May 1980, Miami will have more than one thing to deal with.",
    C('MAY 1980', 'THE VERDICT IS COMING', 'Tampa, Florida', size=170), sfx='tension'),
])

CH8 = dict(title='The Bus', years='April 1980', mood='clock', beats=[
  B("Havana. Tuesday, the first of April 1980. A young man called Héctor Sanyustiz has been planning something in secret for months.",
    S('day', town(n=14, col='#d8c8a8'), palms(y=.88, n=3), push=.05), date="TUESDAY, 1 APRIL 1980\nHAVANA"),
  B("He and four others get on a city bus, route 79, a British made Leyland. One of them is the driver, a friend in on the plan.",
    S('day', town(n=12, col='#d8c8a8'), bus(drive=[1.3, .5, 0, 4])),
    ('Leyland', S('day', bus(x=.5, y=1.05, s=1.4), push=.1))),
  B("A few blocks from Embassy Row, the driver announces the bus has broken down. Everyone gets off. Everyone except the five of them.",
    S('day', town(n=12, col='#d8c8a8'), bus(x=.55), crowd(n=20, y=1.0)),
    ('five', S('day', bus(x=.5, y=1.02, s=1.3), push=.15))),
  T([('DRV', "Everybody off. The bus is broken."), ('PAS', "Again?"), ('HEC', "Stay on the bus.")],
    S('day', town(n=10, col='#d8c8a8'), bus(x=.5, y=.95, s=.9), A(('refugee', .2, 'point'), ('refugee_woman', .8, 'shrug')))),
  B("Sanyustiz takes the wheel and floors it towards the embassy of Peru. Cuban guards outside open fire on the bus.",
    S('day', town(n=10, col='#e8dcc8'), fence(broken=None), bus(drive=[-.3, .45, 0, 3.5], y=.95)),
    ('fire', S('day', fence(), A(('cuban_soldier', .3, 'fire', {'prop': 'rifle'}), ('cuban_soldier', .7, 'aim', {'prop': 'rifle', 'facing': -1})), fx=['smoke'])), sfx='braam'),
  B("The bus smashes through the fence onto the embassy grounds, Peruvian territory. Sanyustiz is wounded. And one of the guards, Pedro Ortiz Cabrera, is killed, hit by a bullet from the guards' own crossfire.",
    S('day', fence(broken=.55), bus(x=.55, y=.95), fx=['dust', 'smoke'], push=.15),
    ('Ortiz', D(['Pedro Ortiz Cabrera', 'Cuban guard', 'killed 1 April 1980'], 'In memory', hl=[0]))),
  B("The Peruvian diplomat in charge, Ernesto Pinto Bazurco, grants the five asylum. Cuba demands them back, to be tried for the guard's death. Peru refuses.",
    S('day', room(flag='pe', window=.6), table(papers=6), A(('politician', .4, 'cross'))),
    ('refuses', S('day', room(flag='cu', window=.6), table(papers=4), A(('castro', .5, 'point', {'mood': 'angry'}))))),
  T([('CUB', "Hand them over."), ('PER', "They asked for asylum. They have it."), ('CUB', "Then you can guard them yourselves.", 'angry')],
    S('day', room(window=.6, wall='#4a4a52'), table(papers=4, w=700), A(('cuban_soldier', .3, 'point'), ('politician', .7, 'cross')))),
  B("On Good Friday, the fourth of April, Castro pulls every guard away from the Peruvian embassy. The statement from Havana says the embassy will now be solely responsible for whatever happens there.",
    D(['"From now on, the embassy\'s officials', 'will be solely responsible', 'for what occurs in their embassy."'], 'Statement from Havana, 4 April 1980', hl=[1]),
    ('Good', C('GOOD FRIDAY', '4 APRIL 1980', 'the guards are withdrawn', size=170))),
  B("Word spreads through Havana by mouth. And within about forty eight hours, around ten thousand eight hundred people pour into the embassy grounds.",
    S('day', fence(), crowd(n=120, y=1.0), push=.06),
    ('ten', C('10,800', 'PEOPLE INSIDE THE EMBASSY', 'in about 48 hours', size=200))),
  B("More than ten thousand people cram into the embassy's gardens. From Washington's side, this is proof of how many Cubans want out. From Castro's side, the people in that garden are criminals, bums and anti socials, and he wants the world to know it.",
    S('day', crowd(n=160, y=1.0), forest(y=.62, n=20, h=200), push=.04),
    ('Castro', D(['"Common delinquents, antisocials,', 'vagrants and bums"'], 'How the Cuban government described them, 1980', hl=[0]))),
  T([('CRD1', "Peru? Are they taking us to Peru?"), ('CRD2', "I don't care where. Anywhere.")],
    S('day', crowd(n=80, y=1.02), A(('refugee', .35, 'think'), ('refugee_woman', .65, 'idle')))),
  B("Then Castro surprises everyone. On the twentieth of April, he announces that anybody who wants to leave Cuba can go, through the port of Mariel, west of Havana. As long as someone comes to pick them up.",
    S('day', sea(y=.6), coast(x0=-.1, x1=.4, y=.6), ships(n=2, flag='cu', s=.4, steam=True)),
    ('Mariel', MAP)),
  B("Miami's Cubans don't need telling twice. Exiles in pleasure boats and shrimp boats head south across the Florida Straits to fetch their families.",
    S('day', sea(y=.56), boats(n=4, crowded=False, y=.72, drift=1.2), push=.06),
    ('families', S('dawn', sea(y=.6), boats(n=3, crowded=False, y=.74, s=.8, x=.2, gap=.3)))),
  B("On the twenty first of April, the first boat from Mariel ties up in Key West, with forty eight people on board. A bus that drove through a fence has just opened a door between two countries.",
    S('day', sea(y=.6), coast(x0=.5, x1=1.2, y=.62), boats(n=1, y=.74, s=.9, x=.35), crowd(n=30, y=1.0)),
    ('door', C('48', 'THE FIRST BOAT FROM MARIEL', 'Key West, 21 April 1980', size=200)), sfx='riser'),
])
